+describe("issue #9735 proxy-reported truncated stream retry", () => {
+	const harnesses: Harness[] = [];
+
+	afterEach(() => {
+		while (harnesses.length > 0) {
+			harnesses.pop()?.cleanup();
+		}
+	});
+
+	const truncatedStreamMessages = [
